package com.complaintbox.controller; import com.complaintbox.dto.AuthDtos.*; import com.complaintbox.service.AuthService; import jakarta.servlet.http.HttpSession; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController{final AuthService auth;public AuthController(AuthService a){auth=a;}@PostMapping("/login")Object login(@RequestBody Login x,HttpSession s){return auth.login(x,s);}@PostMapping("/register")Object register(@RequestBody Register x,HttpSession s){return auth.register(x,s);}@GetMapping("/me")Object me(HttpSession s){return auth.me(s);}@PostMapping("/logout")Object logout(HttpSession s){auth.logout(s);return Map.of("success",true);}}
